import { BundledVault, Project } from '../types/worldify';
import { useWorldifyStore } from '../store/useWorldifyStore';

/**
 * Projects generated by scripts/import-obsidian.mjs live in public/vaults/.
 * On start-up we add any that aren't in the user's library yet, and flag
 * the ones that have a newer import than the copy the user has.
 */
export async function syncBundledVaults(): Promise<void> {
  let index: BundledVault[];
  try {
    const res = await fetch('/vaults/index.json', { cache: 'no-cache' });
    if (!res.ok) return;
    index = await res.json();
  } catch {
    return; // no bundled vaults
  }

  const { projects, importProjectVault, setVaultUpdates } = useWorldifyStore.getState();
  const updates: Record<string, BundledVault> = {};

  for (const entry of index) {
    const existing = projects.find((p) => p.id === entry.projectId);
    if (!existing) {
      const project = await fetchBundledProject(entry);
      if (project) importProjectVault([project]);
    } else if (existing.importedFrom && existing.importedFrom.importedAt < entry.importedAt) {
      updates[entry.projectId] = entry;
    }
  }
  setVaultUpdates(updates);
}

export async function fetchBundledProject(entry: BundledVault): Promise<Project | null> {
  try {
    const res = await fetch(entry.url, { cache: 'no-cache' });
    if (!res.ok) return null;
    return (await res.json()) as Project;
  } catch {
    return null;
  }
}
